-- Section 01A Histoire. Schéma livré, non appliqué sur la base.
-- Questions : corpus. Réponses : une ligne par question d'un test.
-- Score : une ligne par section et par utilisateur, pour chaque série.

CREATE TABLE IF NOT EXISTS formation_question (
  fq_section VARCHAR(32) NOT NULL,
  fq_numero INT NOT NULL,
  fq_page INT NOT NULL,
  fq_kind VARCHAR(8) NOT NULL,
  fq_prompt TEXT NOT NULL,
  fq_choices TEXT NULL,
  fq_answer TEXT NOT NULL,
  PRIMARY KEY (fq_section, fq_numero)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS formation_serie (
  fs_id BIGINT NOT NULL AUTO_INCREMENT,
  fs_user INT NOT NULL,
  fs_section VARCHAR(32) NOT NULL,
  fs_questions VARCHAR(255) NOT NULL,
  fs_created DATETIME NOT NULL,
  PRIMARY KEY (fs_id),
  KEY ix_formation_serie_user (fs_user, fs_section)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS formation_reponse (
  fr_id BIGINT NOT NULL AUTO_INCREMENT,
  fr_serie BIGINT NOT NULL,
  fr_user INT NOT NULL,
  fr_ordre INT NOT NULL,
  fr_question INT NOT NULL,
  fr_resultat CHAR(1) NOT NULL,
  fr_created DATETIME NOT NULL,
  PRIMARY KEY (fr_id),
  UNIQUE KEY ux_formation_reponse (fr_serie, fr_ordre),
  KEY ix_formation_reponse_user (fr_user, fr_serie)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS formation_score (
  fsc_id BIGINT NOT NULL AUTO_INCREMENT,
  fsc_user INT NOT NULL,
  fsc_section VARCHAR(32) NOT NULL,
  fsc_serie BIGINT NOT NULL,
  fsc_score INT NOT NULL,
  fsc_total INT NOT NULL,
  fsc_created DATETIME NOT NULL,
  PRIMARY KEY (fsc_id),
  UNIQUE KEY ux_formation_score_serie (fsc_serie),
  KEY ix_formation_score_user (fsc_user, fsc_section)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

